// 动态导入代码分离
setTimeout(() => {
  // 只有调用 import() 才会加载 another 模块，webpack会自动将这个模块代码分离成一个单独的文件
  import(
    /* webpackPrefetch: true */
    /* webpackChunkName: "import_another" */
    "./another"
  ).then((another) => {
    setTimeout(() => {
      console.log(another.default.join(["Hello", "Another", "Import"], " "));
    }, 2000);
  });
}, 8000);

